def euler(F,x0,y0,h,count):
 hh=mp.mpf(str(h));xx=mp.mpf(str(x0));yy=mp.mpf(str(y0));vals=[]
 for j in range(count):yy+=hh*F(xx,yy);xx=mp.mpf(str(x0))+(j+1)*hh;vals.append(yy)
 return vals
